# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, offset=-1):
    return [v + offset for v in xs]

# region: render
def render(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: fold
def fold(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return fold(render(digest(intake(shape(gather(raw))))))

